    "Tamgaly Petroglyphs":["Таңбалы петроглифтері", "Петроглифы Тамгалы"],
    "Charyn Canyon":["Шарын шатқалы", "Чарынский каньон"],
    "Burabay National Park":["Бурабай ұлттық паркі", "Национальный парк Бурабай"],
    "A dramatic canyon landscape in southeastern Kazakhstan.":["Қазақстанның оңтүстік-шығысындағы көркем шатқал.", "Впечатляющий каньон на юго-востоке Казахстана."],
    "A landscape containing rock carvings that document ancient beliefs and everyday life.":["Көне наным-сенімдер мен тұрмысты бейнелейтін жартас суреттері бар өлке.", "Пейзаж с наскальными рисунками, отражающими древние верования и повседневную жизнь."],
    "A well-known landscape of lakes, forests and distinctive rock formations.":["Көлдерімен, ормандарымен және ерекше жартас түзілімдерімен танымал өлке.", "Известный пейзаж с озёрами, лесами и необычными скальными образованиями."],
    "A historic city associated with important cultural and spiritual traditions.":["Маңызды мәдени және рухани дәстүрлермен байланысты тарихи қала.", "Исторический город, связанный с важными культурными и духовными традициями."],
    "A portable dwelling designed for a nomadic way of life.":["\u041a\u04e9\u0448\u043f\u0435\u043b\u0456 \u04e9\u043c\u0456\u0440 \u0441\u0430\u043b\u0442\u044b\u043d\u0430 \u0430\u0440\u043d\u0430\u043b\u0493\u0430\u043d \u0436\u0438\u043d\u0430\u043b\u043c\u0430\u043b\u044b \u0431\u0430\u0441\u043f\u0430\u043d\u0430.", "\u041f\u0435\u0440\u0435\u043d\u043e\u0441\u043d\u043e\u0435 \u0436\u0438\u043b\u0438\u0449\u0435 \u0434\u043b\u044f \u043a\u043e\u0447\u0435\u0432\u043e\u0433\u043e \u043e\u0431\u0440\u0430\u0437\u0430 \u0436\u0438\u0437\u043d\u0438."],
    "Rock carvings that preserve traces of ancient life.":["\u041a\u04e9\u043d\u0435 \u04e9\u043c\u0456\u0440\u0434\u0456\u04a3 \u0456\u0437\u0434\u0435\u0440\u0456\u043d \u0441\u0430\u049b\u0442\u0430\u0493\u0430\u043d \u0436\u0430\u0440\u0442\u0430\u0441 \u0441\u0443\u0440\u0435\u0442\u0442\u0435\u0440\u0456.", "\u041d\u0430\u0441\u043a\u0430\u043b\u044c\u043d\u044b\u0435 \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u044f, \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0432\u0448\u0438\u0435 \u0441\u043b\u0435\u0434\u044b \u0434\u0440\u0435\u0432\u043d\u0435\u0439 \u0436\u0438\u0437\u043d\u0438."],
    "Cultural practices passed between generations.":["\u04b0\u0440\u043f\u0430\u049b\u0442\u0430\u043d \u04b1\u0440\u043f\u0430\u049b\u049b\u0430 \u0436\u0430\u043b\u0493\u0430\u0441\u049b\u0430\u043d \u043c\u04d9\u0434\u0435\u043d\u0438 \u0434\u04d9\u0441\u0442\u04af\u0440\u043b\u0435\u0440.", "\u041a\u0443\u043b\u044c\u0442\u0443\u0440\u043d\u044b\u0435 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0438, \u043f\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0435\u043c\u044b\u0435 \u0438\u0437 \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f \u0432 \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u0435."],
    "A landmark of medieval architecture in Turkistan.":["\u0422\u04af\u0440\u043a\u0456\u0441\u0442\u0430\u043d\u0434\u0430\u0493\u044b \u043e\u0440\u0442\u0430\u0493\u0430\u0441\u044b\u0440\u043b\u044b\u049b \u0441\u04d9\u0443\u043b\u0435\u0442 \u04e9\u043d\u0435\u0440\u0456\u043d\u0456\u04a3 \u043a\u04e9\u0440\u043d\u0435\u043a\u0442\u0456 \u0435\u0441\u043a\u0435\u0440\u0442\u043a\u0456\u0448\u0456.", "\u0412\u044b\u0434\u0430\u044e\u0449\u0438\u0439\u0441\u044f \u043f\u0430\u043c\u044f\u0442\u043d\u0438\u043a \u0441\u0440\u0435\u0434\u043d\u0435\u0432\u0435\u043a\u043e\u0432\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b \u0422\u0443\u0440\u043a\u0435\u0441\u0442\u0430\u043d\u0430."],
    "Loading additional information\u2026":["\u049a\u043e\u0441\u044b\u043c\u0448\u0430 \u0430\u049b\u043f\u0430\u0440\u0430\u0442 \u0436\u04af\u043a\u0442\u0435\u043b\u0443\u0434\u0435\u2026", "\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0438\u2026"],
    "Yasawi Mausoleum":["\u042f\u0441\u0430\u0443\u0438 \u043a\u0435\u0441\u0435\u043d\u0435\u0441\u0456", "\u041c\u0430\u0432\u0437\u043e\u043b\u0435\u0439 \u042f\u0441\u0430\u0432\u0438"],
